// ServicoSolicitadoFormModal.js
import React, { useEffect, useState } from 'react';
import api from '../../api/axios';
import './servicos-solicitados.css';
import Select from 'react-select';
import { paraISO, paraBR } from '../../utils/datas';

// --- Helpers para tela dd-mm-yyyy ---
const toBRHifen = (iso) => {
  if (!iso) return '';
  return paraBR(iso).replace(/\//g, '-'); // dd/mm/yyyy -> dd-mm-yyyy
};
const toISO = (brHifen) => {
  // aceita dd-mm-yyyy ou dd/mm/yyyy (o paraISO já trata os dois)
  return paraISO(brHifen);
};

// --- Máscara e normalização (igual pattern usado em EmpresaFormModal) ---
const mascararData = (valor) => {
  const d = valor.replace(/[^\d]/g, "").slice(0, 8); // ddmmyyyy
  if (!d) return "";
  if (d.length <= 2) return d;
  if (d.length <= 4) return `${d.slice(0, 2)}-${d.slice(2)}`;
  return `${d.slice(0, 2)}-${d.slice(2, 4)}-${d.slice(4)}`;
};

const normalizarData = (valor) => {
  const d = valor.replace(/[^\d]/g, "");
  if (d.length < 8) return valor; // mantém se incompleta
  let dia = parseInt(d.slice(0, 2), 10);
  let mes = parseInt(d.slice(2, 4), 10);
  let ano = parseInt(d.slice(4, 8), 10);
  if (dia < 1) dia = 1;
  if (dia > 31) dia = 31;
  if (mes < 1) mes = 1;
  if (mes > 12) mes = 12;
  if (ano < 1900) ano = 1900;
  const DD = String(dia).padStart(2, "0");
  const MM = String(mes).padStart(2, "0");
  const YYYY = String(ano).padStart(4, "0");
  return `${DD}-${MM}-${YYYY}`;
};

export default function ServicoSolicitadoFormModal({ dados, fechar }) {
  const [form, setForm] = useState({});
  const [empresas, setEmpresas] = useState([]);
  const [servicos, setServicos] = useState([]);

  useEffect(() => {
    const init = async () => {
      await carregarDadosAuxiliares();

      if (dados) {
        // converte datas ISO que vierem da API para dd-mm-yyyy na tela
        const limpa = { ...dados };
        delete limpa.empresa_id;

        limpa.data_solicitacao   = toBRHifen(dados.data_solicitacao);
        limpa.data_vencimento    = toBRHifen(dados.data_vencimento);
        limpa.data_para_resposta = toBRHifen(dados.data_para_resposta);
        limpa.data_conclusao     = toBRHifen(dados.data_conclusao);

        setForm(limpa);
      } else {
        const hojeISO = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
        setForm((f) => ({ ...f, data_solicitacao: toBRHifen(hojeISO) }));
      }
    };
    init();
  }, [dados]);

  const carregarDadosAuxiliares = async () => {
    const [resEmp, resServ] = await Promise.all([
      api.get('/api/empresas/', { params: { page: 1, page_size: 2000 } }),
      api.get('/api/servicos/')
    ]);
    setEmpresas(resEmp.data.results || resEmp.data);
    setServicos(resServ.data.results || resServ.data);
  };

  // inputs de texto (exceto datas)
  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: (value ?? '').toUpperCase() }));
  };

  // máscara de datas no onChange
  const handleChangeDataMask = (e) => {
    const { name, value } = e.target;
    const val = mascararData(value);
    setForm((prev) => ({ ...prev, [name]: val }));
  };

  // normalização de datas no onBlur
  const handleBlurDataNormalize = (e) => {
    const { name, value } = e.target;
    const val = normalizarData(value);
    setForm((prev) => ({ ...prev, [name]: val }));
  };

  // quando troca o serviço: recalcula data_vencimento
  const handleServicoChange = (e) => {
    const { value } = e.target;
    const servico = servicos.find(s => String(s.id) === String(value));

    // data_solicitacao está em dd-mm-yyyy na tela -> converter para ISO
    const dataSolicBR = form.data_solicitacao || toBRHifen(new Date().toISOString().split('T')[0]);
    const dataSolicISO = toISO(dataSolicBR);
    const base = new Date(dataSolicISO); // YYYY-MM-DD -> Date

    const prazoDias = Number(servico?.prazo_dias || 0);
    const venc = new Date(base);
    venc.setDate(venc.getDate() + prazoDias);

    const vencISO = venc.toISOString().split('T')[0];
    const vencBRHifen = toBRHifen(vencISO);

    setForm(prev => ({ ...prev, servico: value, data_vencimento: vencBRHifen }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Converte as datas de dd-mm-yyyy (tela) -> YYYY-MM-DD (API)
    const payload = {
      ...form,
      data_solicitacao:   form.data_solicitacao   ? toISO(form.data_solicitacao)   : null,
      data_vencimento:    form.data_vencimento    ? toISO(form.data_vencimento)    : null,
      data_para_resposta: form.data_para_resposta ? toISO(form.data_para_resposta) : null,
      data_conclusao:     form.data_conclusao     ? toISO(form.data_conclusao)     : null,
    };

    // remove qualquer resquício que não faça parte do modelo
    delete payload.empresa_id;

    if (dados?.id) await api.put(`/api/solicitacoes/${dados.id}/`, payload);
    else await api.post('/api/solicitacoes/', payload);

    fechar();
  };

  const renderInput = (name, label, tipo = 'text', classe = 'campo-medio', disabled = false) => (
    <div className={`campo ${classe}`} key={name}>
      <label>{label}</label>
      <input
        type={tipo}
        name={name}
        value={form[name] || ''}
        onChange={handleChange}
        disabled={disabled}
      />
    </div>
  );

  // input de data com máscara dd-mm-yyyy
  const renderInputData = (name, label, classe = 'campo-medio', disabled = false) => (
    <div className={`campo ${classe}`} key={name}>
      <label>{label}</label>
      <input
        type="text"
        name={name}
        value={form[name] || ''}
        onChange={handleChangeDataMask}
        onBlur={handleBlurDataNormalize}
        placeholder="dd-mm-aaaa"
        maxLength={10}
        inputMode="numeric"
        autoComplete="off"
        disabled={disabled}
      />
    </div>
  );

  return (
    <div className="modal-overlay">
      <div className="modal">
        <h3>{dados ? 'EDITAR SERVIÇO SOLICITADO' : 'NOVO SERVIÇO SOLICITADO'}</h3>
        <form onSubmit={handleSubmit} className="modal-form">

          <div className="linha">
            <div className="campo campo-longo">
              <label>EMPRESA</label>
              <Select
                options={empresas.map(emp => ({
                  value: emp.cod_folha,
                  label: `${emp.cod_folha} - ${emp.razao_social}`
                }))}
                value={empresas
                  .map(emp => ({
                    value: emp.cod_folha,
                    label: `${emp.cod_folha} - ${emp.razao_social}`
                  }))
                  .find(opt => String(opt.value) === String(form.empresa))}
                onChange={opt => {
                  const novo = { ...form };
                  delete novo.empresa_id;
                  novo.empresa = opt?.value || '';
                  setForm(novo);
                }}
                placeholder="Digite para buscar..."
                isClearable
              />
            </div>
          </div>

          <div className="linha">
            <div className="campo campo-medio">
              <label>SERVIÇO</label>
              <select name="servico" value={form.servico || ''} onChange={handleServicoChange}>
                <option value="">--</option>
                {servicos.map(s => (
                  <option key={s.id} value={s.id}>{s.nome}</option>
                ))}
              </select>
            </div>
            {renderInput('competencia', 'COMPETÊNCIA', 'text', 'campo-curto')}
            {renderInput('identificacao', 'IDENTIFICAÇÃO', 'text', 'campo-longo')}
          </div>

          <div className="linha">
            {renderInputData('data_solicitacao', 'SOLICITAÇÃO', 'campo-curto')}
            {renderInputData('data_vencimento', 'VENCIMENTO', 'campo-curto', true)}
            {renderInputData('data_para_resposta', 'DATA PARA RESPOSTA', 'campo-curto')}
            {renderInputData('data_conclusao', 'CONCLUSÃO', 'campo-curto')}
          </div>

          <div className="linha">
            <div className="campo campo-longo">
              <label>DESCRIÇÃO DO SERVIÇO</label>
              <textarea
                name="descricao_servico"
                value={form.descricao_servico || ''}
                onChange={handleChange}
              />
            </div>
          </div>

          <div className="botoes">
            <button type="submit">SALVAR</button>
            <button type="button" className="cancelar" onClick={fechar}>CANCELAR</button>
          </div>
        </form>
      </div>
    </div>
  );
}
